#!/usr/bin/env bash
set -euo pipefail

is_precommit_pre_push_shim() {
  local actual expected
  actual=$(sed -E \
    -e 's/^# ID: [[:xdigit:]]{32}$/# ID: <id>/' \
    -e 's|^INSTALL_PYTHON=.*$|INSTALL_PYTHON=<python>|' "$1") || return 1
  expected=$(cat <<'EOF'
#!/usr/bin/env bash
# File generated by pre-commit: https://pre-commit.com
# ID: <id>

# start templated
INSTALL_PYTHON=<python>
ARGS=(hook-impl --config=.pre-commit-config.yaml --hook-type=pre-push)
# end templated

HERE="$(cd "$(dirname "$0")" && pwd)"
ARGS+=(--hook-dir "$HERE" -- "$@")

if [ -x "$INSTALL_PYTHON" ]; then
    exec "$INSTALL_PYTHON" -mpre_commit "${ARGS[@]}"
elif command -v pre-commit > /dev/null; then
    exec pre-commit "${ARGS[@]}"
else
    echo '`pre-commit` not found.  Did you forget to activate your virtualenv?' 1>&2
    exit 1
fi
EOF
  )
  [[ $actual == "$expected" ]]
}

install_hook() {
  local hook_path script_path
  script_path=${BASH_SOURCE[0]}
  hook_path=$(git rev-parse --git-path hooks/pre-push)
  [[ $hook_path == /* ]] || hook_path="$PWD/$hook_path"

  if [[ -L $hook_path ]]; then
    printf 'Refusing to replace symlinked pre-push hook: %s\n' "$hook_path" >&2
    return 1
  fi
  if [[ -e $hook_path ]]; then
    if cmp -s "$script_path" "$hook_path"; then
      chmod +x "$hook_path"
      return 0
    fi
    if ! is_precommit_pre_push_shim "$hook_path"; then
      printf 'Refusing to replace unknown pre-push hook: %s\n' "$hook_path" >&2
      return 1
    fi
  fi

  mkdir -p "$(dirname "$hook_path")"
  cp "$script_path" "$hook_path"
  chmod +x "$hook_path"
}

if [[ ${1:-} == --install ]]; then
  if [[ $# -ne 1 ]]; then
    printf 'Usage: %s --install\n' "$0" >&2
    exit 2
  fi
  install_hook
  exit
fi

if [[ $# -lt 1 ]]; then
  printf 'Cannot identify the push remote; refusing push.\n' >&2
  exit 1
fi
[[ $1 == origin ]] || exit 0

branch_updates=
branch_count=0
while IFS= read -r update || [[ -n $update ]]; do
  [[ -n $update ]] || continue
  local_ref=
  local_sha=
  remote_ref=
  remote_sha=
  extra=
  read -r local_ref local_sha remote_ref remote_sha extra <<< "$update"
  if [[ -z $local_ref || -z $local_sha || -z $remote_ref || -z $remote_sha || -n $extra ]]; then
    printf 'Cannot parse pre-push update; refusing push.\n' >&2
    exit 1
  fi
  [[ $remote_ref == refs/heads/* ]] || continue
  [[ $local_sha =~ ^0+$ ]] && continue
  if [[ ! $local_sha =~ ^[[:xdigit:]]+$ || ! $remote_sha =~ ^[[:xdigit:]]+$ ]]; then
    printf 'Cannot verify pre-push update for %s; refusing push.\n' "$remote_ref" >&2
    exit 1
  fi
  branch_updates+="$remote_ref"$'\t'"$local_sha"$'\n'
  branch_count=$((branch_count + 1))
done

[[ $branch_count -gt 0 ]] || exit 0
git fetch --quiet origin +refs/heads/main:refs/remotes/origin/main

failed=0
while IFS=$'\t' read -r remote_ref pushed_sha; do
  [[ -n $remote_ref ]] || continue
  if ! git cat-file -e "${pushed_sha}^{commit}" 2>/dev/null; then
    printf 'Cannot verify pushed commit for %s; refusing push.\n' "$remote_ref" >&2
    failed=1
    continue
  fi
  if ! git merge-base --is-ancestor refs/remotes/origin/main "$pushed_sha"; then
    printf 'Push blocked: %s does not contain the latest origin/main (%s). Merge or rebase origin/main, then retry.\n' \
      "${remote_ref#refs/heads/}" "$(git rev-parse --short refs/remotes/origin/main)" >&2
    failed=1
  fi
done <<< "$branch_updates"

exit "$failed"
